[CmdletBinding()] param()

if ($PSVersionTable.PSEdition -ne 'Desktop') { throw 'Run this app with Windows PowerShell 5.1 (powershell.exe).' }
Add-Type -AssemblyName PresentationFramework,PresentationCore,WindowsBase,System.Xaml
trap {[void][Windows.MessageBox]::Show($_.Exception.Message,'Polynt IT Toolbox','OK','Error');break}
. (Join-Path $PSScriptRoot 'functions.ps1')

$xaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Polynt IT Toolbox" Width="1180" Height="860" MinWidth="1020" MinHeight="740"
        WindowStartupLocation="CenterScreen" FontFamily="Segoe UI" FontSize="13" Background="{DynamicResource WindowBrush}">
  <Window.Resources>
    <SolidColorBrush x:Key="WindowBrush" Color="#F3F6FA"/><SolidColorBrush x:Key="SurfaceBrush" Color="#FFFFFF"/>
    <SolidColorBrush x:Key="CardBrush" Color="#FFFFFF"/><SolidColorBrush x:Key="InputBrush" Color="#FFFFFF"/>
    <SolidColorBrush x:Key="TextBrush" Color="#172033"/><SolidColorBrush x:Key="MutedBrush" Color="#5B687A"/>
    <SolidColorBrush x:Key="BorderBrush" Color="#CBD5E1"/><SolidColorBrush x:Key="AccentBrush" Color="#2878D0"/>
    <SolidColorBrush x:Key="ButtonBrush" Color="#EEF3F8"/><SolidColorBrush x:Key="SelectionBrush" Color="#DCE6F1"/><SolidColorBrush x:Key="PressedBrush" Color="#CCD8E5"/><SolidColorBrush x:Key="OutputBrush" Color="#FBFCFE"/>
    <SolidColorBrush x:Key="ScrollThumbBrush" Color="#A8B2BF"/><SolidColorBrush x:Key="ScrollThumbHoverBrush" Color="#7C8998"/>
    <SolidColorBrush x:Key="HeaderTextBrush" Color="#FFFFFF"/>
    <Style TargetType="TextBlock"><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/></Style>
    <Style TargetType="Label"><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/><Setter Property="VerticalContentAlignment" Value="Center"/></Style>
    <Style TargetType="Button"><Setter Property="Background" Value="{DynamicResource ButtonBrush}"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/><Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/><Setter Property="Padding" Value="11,5"/><Setter Property="Margin" Value="0,0,8,6"/><Setter Property="MinHeight" Value="30"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button"><Border x:Name="ButtonBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="4" Padding="{TemplateBinding Padding}"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="ButtonBorder" Property="Background" Value="{DynamicResource SelectionBrush}"/></Trigger><Trigger Property="IsPressed" Value="True"><Setter TargetName="ButtonBorder" Property="Background" Value="{DynamicResource PressedBrush}"/></Trigger><Trigger Property="IsEnabled" Value="False"><Setter Property="Opacity" Value="0.45"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
    <Style TargetType="TextBox"><Setter Property="Background" Value="{DynamicResource InputBrush}"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/><Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/><Setter Property="Padding" Value="6,2"/><Setter Property="MinHeight" Value="28"/><Setter Property="VerticalContentAlignment" Value="Center"/></Style>
    <Style TargetType="PasswordBox"><Setter Property="Background" Value="{DynamicResource InputBrush}"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/><Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/><Setter Property="Padding" Value="6,2"/><Setter Property="MinHeight" Value="28"/><Setter Property="VerticalContentAlignment" Value="Center"/></Style>
    <Style TargetType="ComboBox"><Setter Property="Background" Value="{DynamicResource InputBrush}"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/><Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/><Setter Property="Padding" Value="4"/><Setter Property="MinHeight" Value="28"/><Setter Property="MaxDropDownHeight" Value="320"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ComboBox"><Grid><Border x:Name="ComboBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="3"><Grid><ContentPresenter x:Name="ContentSite" Margin="8,0,30,0" VerticalAlignment="Center" Content="{TemplateBinding SelectionBoxItem}" ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}" ContentStringFormat="{TemplateBinding SelectionBoxItemStringFormat}"/><TextBox x:Name="PART_EditableTextBox" Margin="7,1,30,1" Padding="0" Background="Transparent" BorderThickness="0" Foreground="{TemplateBinding Foreground}" CaretBrush="{DynamicResource TextBrush}" VerticalContentAlignment="Center" Visibility="Hidden" IsReadOnly="{TemplateBinding IsReadOnly}" Text="{Binding Text, RelativeSource={RelativeSource TemplatedParent}, Mode=TwoWay, UpdateSourceTrigger=PropertyChanged}"/><Path HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,10,0" Fill="{TemplateBinding Foreground}" Data="M 0 0 L 5 5 L 10 0 Z"/></Grid></Border><ToggleButton x:Name="DropDownToggle" Background="Transparent" BorderThickness="0" Focusable="False" ClickMode="Press" IsChecked="{Binding IsDropDownOpen, RelativeSource={RelativeSource TemplatedParent}, Mode=TwoWay}"><ToggleButton.Template><ControlTemplate TargetType="ToggleButton"><Border Background="Transparent"/></ControlTemplate></ToggleButton.Template></ToggleButton><Popup x:Name="PART_Popup" Placement="Bottom" AllowsTransparency="True" Focusable="False" IsOpen="{TemplateBinding IsDropDownOpen}" PopupAnimation="Fade"><Border Background="{DynamicResource InputBrush}" BorderBrush="{DynamicResource BorderBrush}" BorderThickness="1" CornerRadius="3" MinWidth="{Binding ActualWidth, RelativeSource={RelativeSource TemplatedParent}}" MaxHeight="{TemplateBinding MaxDropDownHeight}"><ScrollViewer CanContentScroll="True" VerticalScrollBarVisibility="Auto"><ItemsPresenter KeyboardNavigation.DirectionalNavigation="Contained"/></ScrollViewer></Border></Popup></Grid><ControlTemplate.Triggers><Trigger Property="IsEditable" Value="True"><Setter TargetName="ContentSite" Property="Visibility" Value="Hidden"/><Setter TargetName="PART_EditableTextBox" Property="Visibility" Value="Visible"/><Setter TargetName="DropDownToggle" Property="HorizontalAlignment" Value="Right"/><Setter TargetName="DropDownToggle" Property="Width" Value="30"/></Trigger><Trigger Property="IsKeyboardFocusWithin" Value="True"><Setter TargetName="ComboBorder" Property="BorderBrush" Value="{DynamicResource TextBrush}"/></Trigger><Trigger Property="IsEnabled" Value="False"><Setter Property="Opacity" Value="0.45"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
    <Style TargetType="ComboBoxItem"><Setter Property="Background" Value="{DynamicResource InputBrush}"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/><Setter Property="Padding" Value="8,6"/><Setter Property="HorizontalContentAlignment" Value="Stretch"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ComboBoxItem"><Border x:Name="ItemBorder" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}"><ContentPresenter/></Border><ControlTemplate.Triggers><Trigger Property="IsHighlighted" Value="True"><Setter TargetName="ItemBorder" Property="Background" Value="{DynamicResource SelectionBrush}"/></Trigger><Trigger Property="IsSelected" Value="True"><Setter TargetName="ItemBorder" Property="Background" Value="{DynamicResource SelectionBrush}"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
    <Style TargetType="ListBox"><Setter Property="Background" Value="{DynamicResource InputBrush}"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/><Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/><Setter Property="Padding" Value="3"/></Style>
    <Style TargetType="ListBoxItem"><Setter Property="Background" Value="Transparent"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/><Setter Property="Padding" Value="4,3"/><Setter Property="HorizontalContentAlignment" Value="Stretch"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ListBoxItem"><Border x:Name="ListItemBorder" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}" CornerRadius="2"><ContentPresenter/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="ListItemBorder" Property="Background" Value="{DynamicResource ButtonBrush}"/></Trigger><Trigger Property="IsSelected" Value="True"><Setter TargetName="ListItemBorder" Property="Background" Value="{DynamicResource SelectionBrush}"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
    <Style TargetType="CheckBox"><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/><Setter Property="Margin" Value="0,5,12,5"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="CheckBox"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="18"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Border x:Name="CheckBorder" Width="15" Height="15" Background="{DynamicResource InputBrush}" BorderBrush="{DynamicResource BorderBrush}" BorderThickness="1" CornerRadius="2" VerticalAlignment="Center"><Path x:Name="CheckMark" Data="M 2 7 L 6 11 L 13 3" Stroke="{DynamicResource TextBrush}" StrokeThickness="2" Visibility="Hidden"/></Border><ContentPresenter Grid.Column="1" Margin="5,0,0,0" VerticalAlignment="Center" RecognizesAccessKey="True"/></Grid><ControlTemplate.Triggers><Trigger Property="IsChecked" Value="True"><Setter TargetName="CheckMark" Property="Visibility" Value="Visible"/><Setter TargetName="CheckBorder" Property="Background" Value="{DynamicResource SelectionBrush}"/></Trigger><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="CheckBorder" Property="BorderBrush" Value="{DynamicResource TextBrush}"/></Trigger><Trigger Property="IsEnabled" Value="False"><Setter Property="Opacity" Value="0.45"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
    <Style TargetType="TabControl"><Setter Property="Background" Value="{DynamicResource SurfaceBrush}"/><Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="TabControl"><Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions><Border Background="{DynamicResource WindowBrush}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="0,0,0,1"><TabPanel IsItemsHost="True"/></Border><Border Grid.Row="1" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1,0,1,1"><ContentPresenter x:Name="PART_SelectedContentHost" Margin="0" ContentSource="SelectedContent"/></Border></Grid></ControlTemplate></Setter.Value></Setter></Style>
    <Style TargetType="TabItem"><Setter Property="Foreground" Value="{DynamicResource MutedBrush}"/><Setter Property="Background" Value="{DynamicResource WindowBrush}"/><Setter Property="BorderBrush" Value="Transparent"/><Setter Property="Padding" Value="15,9"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="TabItem"><Border x:Name="TabBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="0,0,0,2" Padding="{TemplateBinding Padding}"><ContentPresenter ContentSource="Header" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="TabBorder" Property="Background" Value="{DynamicResource ButtonBrush}"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/></Trigger><Trigger Property="IsSelected" Value="True"><Setter TargetName="TabBorder" Property="Background" Value="{DynamicResource SurfaceBrush}"/><Setter TargetName="TabBorder" Property="BorderBrush" Value="{DynamicResource MutedBrush}"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/><Setter Property="FontWeight" Value="SemiBold"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
    <Style TargetType="ContextMenu"><Setter Property="Background" Value="{DynamicResource SurfaceBrush}"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/><Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ContextMenu"><Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" Padding="3"><StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Cycle"/></Border></ControlTemplate></Setter.Value></Setter></Style>
    <Style TargetType="MenuItem"><Setter Property="Background" Value="{DynamicResource SurfaceBrush}"/><Setter Property="Foreground" Value="{DynamicResource TextBrush}"/><Setter Property="Padding" Value="9,6"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="MenuItem"><Border x:Name="MenuItemBorder" Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}"><ContentPresenter ContentSource="Header"/></Border><ControlTemplate.Triggers><Trigger Property="IsHighlighted" Value="True"><Setter TargetName="MenuItemBorder" Property="Background" Value="{DynamicResource SelectionBrush}"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
    <Style x:Key="InvisibleScrollButton" TargetType="RepeatButton"><Setter Property="Focusable" Value="False"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="RepeatButton"><Border Background="Transparent"/></ControlTemplate></Setter.Value></Setter></Style>
    <Style x:Key="SlimScrollThumb" TargetType="Thumb"><Setter Property="MinWidth" Value="8"/><Setter Property="MinHeight" Value="24"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Thumb"><Border x:Name="ThumbBody" Background="{DynamicResource ScrollThumbBrush}" CornerRadius="5" Margin="2"/><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="ThumbBody" Property="Background" Value="{DynamicResource ScrollThumbHoverBrush}"/></Trigger><Trigger Property="IsDragging" Value="True"><Setter TargetName="ThumbBody" Property="Background" Value="{DynamicResource TextBrush}"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
    <Style TargetType="ScrollBar"><Setter Property="Background" Value="Transparent"/><Setter Property="MinWidth" Value="10"/><Setter Property="MinHeight" Value="10"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ScrollBar"><Grid Background="{TemplateBinding Background}"><Track x:Name="PART_Track" Orientation="{TemplateBinding Orientation}" Minimum="{TemplateBinding Minimum}" Maximum="{TemplateBinding Maximum}" Value="{Binding Value, RelativeSource={RelativeSource TemplatedParent}, Mode=TwoWay}" ViewportSize="{TemplateBinding ViewportSize}" IsDirectionReversed="True"><Track.DecreaseRepeatButton><RepeatButton x:Name="DecreaseButton" Style="{StaticResource InvisibleScrollButton}" Command="{x:Static ScrollBar.PageUpCommand}" CommandTarget="{Binding RelativeSource={RelativeSource TemplatedParent}}"/></Track.DecreaseRepeatButton><Track.Thumb><Thumb x:Name="ScrollThumb" Style="{StaticResource SlimScrollThumb}"/></Track.Thumb><Track.IncreaseRepeatButton><RepeatButton x:Name="IncreaseButton" Style="{StaticResource InvisibleScrollButton}" Command="{x:Static ScrollBar.PageDownCommand}" CommandTarget="{Binding RelativeSource={RelativeSource TemplatedParent}}"/></Track.IncreaseRepeatButton></Track></Grid><ControlTemplate.Triggers><Trigger Property="Orientation" Value="Horizontal"><Setter TargetName="PART_Track" Property="IsDirectionReversed" Value="False"/><Setter TargetName="ScrollThumb" Property="MinHeight" Value="8"/><Setter TargetName="ScrollThumb" Property="MinWidth" Value="24"/><Setter TargetName="DecreaseButton" Property="Command" Value="{x:Static ScrollBar.PageLeftCommand}"/><Setter TargetName="IncreaseButton" Property="Command" Value="{x:Static ScrollBar.PageRightCommand}"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
    <Style x:Key="CardStyle" TargetType="Border"><Setter Property="Background" Value="{DynamicResource CardBrush}"/><Setter Property="BorderBrush" Value="{DynamicResource BorderBrush}"/><Setter Property="BorderThickness" Value="1"/><Setter Property="CornerRadius" Value="8"/><Setter Property="Padding" Value="12"/><Setter Property="Margin" Value="0,0,0,9"/></Style>
    <Style x:Key="SectionStyle" TargetType="TextBlock"><Setter Property="FontSize" Value="15"/><Setter Property="FontWeight" Value="SemiBold"/><Setter Property="Margin" Value="0,0,0,9"/></Style>
    <DataTemplate x:Key="DeviceTemplate"><TextBlock Text="{Binding DisplayText}" Foreground="{Binding Foreground, RelativeSource={RelativeSource AncestorType=ListBoxItem}}"><TextBlock.Style><Style TargetType="TextBlock"><Style.Triggers><DataTrigger Binding="{Binding Discontinued}" Value="True"><Setter Property="TextDecorations" Value="Strikethrough"/><Setter Property="Opacity" Value="0.65"/></DataTrigger></Style.Triggers></Style></TextBlock.Style></TextBlock></DataTemplate>
    <DataTemplate x:Key="ReasonTemplate"><TextBlock Text="{Binding Name}"/></DataTemplate>
  </Window.Resources>
  <Grid>
    <Grid.RowDefinitions><RowDefinition Height="52"/><RowDefinition Height="*"/><RowDefinition x:Name="ResultsSplitterRow" Height="0"/><RowDefinition x:Name="ResultsRow" Height="0"/><RowDefinition Height="28"/></Grid.RowDefinitions>
    <Border Grid.Row="0" Background="{DynamicResource SurfaceBrush}" BorderBrush="{DynamicResource BorderBrush}" BorderThickness="0,0,0,1"><Grid Margin="20,0"><Grid.ColumnDefinitions><ColumnDefinition/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Text="IT Toolbox" Foreground="{DynamicResource TextBrush}" FontSize="20" FontWeight="SemiBold" VerticalAlignment="Center"/><TextBlock Grid.Column="1" Text="Polynt" Foreground="{DynamicResource MutedBrush}" FontSize="12" VerticalAlignment="Center"/></Grid></Border>
    <TabControl x:Name="Tabs" Grid.Row="1" Margin="14,12,14,5">
      <TabItem Header="Computers"><ScrollViewer VerticalScrollBarVisibility="Auto"><StackPanel Margin="14">
        <Border Style="{StaticResource CardStyle}"><StackPanel><TextBlock Text="Computer lookup" Style="{StaticResource SectionStyle}"/>
          <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="135"/><ColumnDefinition Width="2*"/><ColumnDefinition Width="70"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
            <Label Content="Computer or IP"/><ComboBox x:Name="Computer" Grid.Column="1" IsEditable="True" Margin="0,0,14,8"/><Label Grid.Column="2" Content="Domain"/><ComboBox x:Name="ComputerDomain" Grid.Column="3" Margin="0,0,14,8"/><Button x:Name="FindComputer" Grid.Column="4" Content="Find computer"/>
          </Grid>
          <Grid Margin="0,4,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="135"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><Label Content="Description contains"/><TextBox x:Name="DescriptionSearch" Grid.Column="1" Margin="0,0,14,8"/><Button x:Name="FindDescriptions" Grid.Column="2" Content="Find matching PCs"/></Grid>
          <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="135"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Label Content="Matches" VerticalAlignment="Top"/><ListBox x:Name="DescriptionResults" Grid.Column="1" Height="92" DisplayMemberPath="DisplayText"/></Grid>
          <Grid Margin="0,10,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="135"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><Label Content="New description"/><TextBox x:Name="NewDescription" Grid.Column="1" Margin="0,0,14,8"/><Button x:Name="SaveDescription" Grid.Column="2" Content="Save description"/></Grid>
        </StackPanel></Border>
        <Border Style="{StaticResource CardStyle}"><StackPanel><TextBlock Text="Computer actions" Style="{StaticResource SectionStyle}"/><WrapPanel>
          <Button x:Name="SerialNumber" Content="Serial number"/><Button x:Name="Ping" Content="Ping"/><Button x:Name="OpenCDrive" Content="Open C drive"/><Button x:Name="RemoteDesktop" Content="Remote Desktop"/><Button x:Name="RemoteAssistance" Content="Remote Assistance"/><Button x:Name="CopyComputer" Content="Copy computer name"/><Button x:Name="LoggedInUser" Content="Logged in user"/><Button x:Name="InstalledSoftware" Content="Installed software"/><Button x:Name="EnableMove" Content="Enable / move"/><Button x:Name="DnsDetails" Content="DNS details"/>
        </WrapPanel><WrapPanel Margin="0,4,0,0"><Button x:Name="ShowLaps" Content="Show LAPS password"/><Button x:Name="CopyLaps" Content="Copy LAPS password"/><Button x:Name="ShowBitLocker" Content="Show BitLocker key"/><Button x:Name="CopyBitLocker" Content="Copy BitLocker key"/></WrapPanel></StackPanel></Border>
        <Border Style="{StaticResource CardStyle}"><StackPanel><TextBlock Text="Administrative tools" Style="{StaticResource SectionStyle}"/><TextBlock Text="Open with the administrator account saved in Settings." Foreground="{DynamicResource MutedBrush}" Margin="0,0,0,14"/><WrapPanel><Button x:Name="AdminShell" Content="Admin PowerShell"/><Button x:Name="Dsa" Content="AD Users &amp; Computers"/><Button x:Name="CompMgmt" Content="Computer Management"/></WrapPanel></StackPanel></Border>
      </StackPanel></ScrollViewer></TabItem>
      <TabItem Header="Users &amp; Groups"><ScrollViewer VerticalScrollBarVisibility="Auto"><StackPanel Margin="14">
        <Border Style="{StaticResource CardStyle}"><StackPanel><TextBlock Text="User account" Style="{StaticResource SectionStyle}"/><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="135"/><ColumnDefinition Width="360"/><ColumnDefinition Width="70"/><ColumnDefinition Width="210"/><ColumnDefinition Width="Auto"/><ColumnDefinition/></Grid.ColumnDefinitions><Label Content="Name or email"/><TextBox x:Name="UserIdentity" Grid.Column="1" Margin="0,0,14,6"/><Label Grid.Column="2" Content="Domain"/><ComboBox x:Name="UserDomain" Grid.Column="3" Margin="0,0,14,6"/><Button x:Name="FindUser" Grid.Column="4" Content="Find user"/></Grid><WrapPanel Margin="135,4,0,0"><Button x:Name="UnlockUser" Content="Unlock account"/><Button x:Name="ResetPassword" Content="Reset password"/></WrapPanel></StackPanel></Border>
        <Border Style="{StaticResource CardStyle}"><StackPanel><TextBlock Text="Group lookup / transfer" Style="{StaticResource SectionStyle}"/><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="84"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
          <Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="185"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="GroupUser1" Margin="0,0,10,8"/><Button x:Name="LoadGroups1" Grid.Column="1" Content="Load groups"/></Grid><ListBox x:Name="Groups1" Grid.Row="1" DisplayMemberPath="Name"/><WrapPanel Grid.Row="2" Margin="0,10,0,0"><Button x:Name="UseUserAbove" Content="Use user above"/><Button x:Name="CopyGroupList1" Content="Copy list"/><Button x:Name="CopyAllGroupsTo2" Content="Copy all &gt;"/></WrapPanel></Grid>
          <StackPanel Grid.Column="1" VerticalAlignment="Center" Margin="10"><Button x:Name="CopyGroupTo2" Content="&gt;"/><Button x:Name="CopyGroupTo1" Content="&lt;"/></StackPanel>
          <Grid Grid.Column="2"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="185"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="GroupUser2" Margin="0,0,10,8"/><Button x:Name="LoadGroups2" Grid.Column="1" Content="Load groups"/></Grid><ListBox x:Name="Groups2" Grid.Row="1" DisplayMemberPath="Name"/><WrapPanel Grid.Row="2" Margin="0,10,0,0"><Button x:Name="CopyAllGroupsTo1" Content="&lt; Copy all"/><Button x:Name="CopyGroupList2" Content="Copy list"/></WrapPanel></Grid>
        </Grid><TextBlock Text="Only missing direct memberships are added; existing memberships are retained." Foreground="{DynamicResource MutedBrush}" Margin="0,10,0,0"/></StackPanel></Border>
      </StackPanel></ScrollViewer></TabItem>
      <TabItem Header="Assets (Assyst)"><ScrollViewer VerticalScrollBarVisibility="Auto"><StackPanel Margin="14">
        <Border Style="{StaticResource CardStyle}"><StackPanel><TextBlock Text="Active item actions" Style="{StaticResource SectionStyle}"/>
          <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="125"/><ColumnDefinition Width="360"/><ColumnDefinition Width="Auto"/><ColumnDefinition Width="Auto"/><ColumnDefinition/></Grid.ColumnDefinitions><Label Content="Item short code"/><ComboBox x:Name="AssystItem" Grid.Column="1" IsEditable="True" Margin="0,0,12,6"/><Button x:Name="FindAssystItem" Grid.Column="2" Content="Find item"/><Button x:Name="UseSelectedComputer" Grid.Column="3" Content="Use computer lookup" ToolTip="Copy the current computer name from the Computers tab into the item short-code field."/></Grid>
          <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="125"/><ColumnDefinition Width="300"/><ColumnDefinition Width="Auto"/><ColumnDefinition/></Grid.ColumnDefinitions><Label Content="Assign to user"/><TextBox x:Name="AssystNewOwner" Grid.Column="1" Margin="0,0,12,6"/><Button x:Name="AssignAssystItem" Grid.Column="2" Content="Assign and deploy"/></Grid>
          <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="125"/><ColumnDefinition Width="220"/><ColumnDefinition Width="Auto"/><ColumnDefinition/></Grid.ColumnDefinitions><Label Content="Put in stock at"/><ComboBox x:Name="StockSite" Grid.Column="1" Margin="0,0,12,8"/><Button x:Name="PutInStock" Grid.Column="2" Content="Put in stock"/></Grid>
          <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="125"/><ColumnDefinition Width="220"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Label Content="Movement reason"/><ComboBox x:Name="MovementReason" Grid.Column="1" Margin="0,0,12,6" ItemTemplate="{StaticResource ReasonTemplate}"/><TextBlock Grid.Column="2" Text="Applies to assignments, transfers and stock movements." Foreground="{DynamicResource MutedBrush}" VerticalAlignment="Center"/></Grid>
        </StackPanel></Border>
        <Border Style="{StaticResource CardStyle}"><StackPanel><DockPanel Margin="0,0,0,10" LastChildFill="False"><TextBlock Text="Owner device lookup / transfer" Style="{StaticResource SectionStyle}" DockPanel.Dock="Left"/><CheckBox x:Name="ShowDiscontinued" Content="Show discontinued items" DockPanel.Dock="Right"/></DockPanel>
          <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="96"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
            <Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="190"/></Grid.RowDefinitions><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="AssystOwner1" Margin="0,0,10,8"/><Button x:Name="FindAssystOwner1" Grid.Column="1" Content="Find"/></Grid><ListBox x:Name="AssystDevices1" Grid.Row="1" ItemTemplate="{StaticResource DeviceTemplate}" HorizontalContentAlignment="Stretch"/></Grid>
            <StackPanel Grid.Column="1" VerticalAlignment="Center" Margin="10"><Button x:Name="TransferToOwner2" Content="&gt;"/><Button x:Name="TransferToOwner1" Content="&lt;"/></StackPanel>
            <Grid Grid.Column="2"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="190"/></Grid.RowDefinitions><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBox x:Name="AssystOwner2" Margin="0,0,10,8"/><Button x:Name="FindAssystOwner2" Grid.Column="1" Content="Find"/></Grid><ListBox x:Name="AssystDevices2" Grid.Row="1" ItemTemplate="{StaticResource DeviceTemplate}" HorizontalContentAlignment="Stretch"/></Grid>
          </Grid>
        </StackPanel></Border>
        <Border Style="{StaticResource CardStyle}"><StackPanel><TextBlock Text="Export items by contract" Style="{StaticResource SectionStyle}"/><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="145"/><ColumnDefinition Width="420"/><ColumnDefinition Width="Auto"/><ColumnDefinition/></Grid.ColumnDefinitions><Label Content="Contract number(s)"/><TextBox x:Name="AssystContracts" Grid.Column="1" Margin="0,0,12,6"/><Button x:Name="ExportContracts" Grid.Column="2" Content="Export CSV"/></Grid></StackPanel></Border>
      </StackPanel></ScrollViewer></TabItem>
      <TabItem Header="Settings"><ScrollViewer VerticalScrollBarVisibility="Auto"><StackPanel Margin="14">
        <Border Style="{StaticResource CardStyle}"><StackPanel><TextBlock Text="Administrator credentials" Style="{StaticResource SectionStyle}"/><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="125"/><ColumnDefinition Width="400"/><ColumnDefinition Width="Auto"/><ColumnDefinition/></Grid.ColumnDefinitions><Grid.RowDefinitions><RowDefinition/><RowDefinition/><RowDefinition/></Grid.RowDefinitions><Label Content="Domain"/><ComboBox x:Name="CredentialDomain" Grid.Column="1" Margin="0,0,12,6"/><Label Grid.Row="1" Content="Username"/><TextBox x:Name="AdminUser" Grid.Row="1" Grid.Column="1" Margin="0,0,12,6"/><Label Grid.Row="2" Content="Password"/><PasswordBox x:Name="AdminPassword" Grid.Row="2" Grid.Column="1" Margin="0,0,12,6"/><Button x:Name="SaveCredential" Grid.RowSpan="3" Grid.Column="2" Content="Save credential" VerticalAlignment="Center"/></Grid><TextBlock Text="Credentials are saved separately for each domain." Foreground="{DynamicResource MutedBrush}" Margin="125,4,0,0"/></StackPanel></Border>
        <Border Style="{StaticResource CardStyle}"><StackPanel><TextBlock Text="Assyst settings" Style="{StaticResource SectionStyle}"/><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="125"/><ColumnDefinition Width="520"/><ColumnDefinition Width="Auto"/><ColumnDefinition/></Grid.ColumnDefinitions><Grid.RowDefinitions><RowDefinition/><RowDefinition/><RowDefinition/></Grid.RowDefinitions><Label Content="API base URL"/><TextBox x:Name="AssystApiBaseBox" Grid.Column="1" Margin="0,0,12,6"/><Label Grid.Row="1" Content="Basic value"/><PasswordBox x:Name="AssystBasic" Grid.Row="1" Grid.Column="1" Margin="0,0,12,6"/><TextBlock Grid.Row="2" Grid.Column="1" Text="Base64 encoded user:password. Leave blank to retain the saved value." Foreground="{DynamicResource MutedBrush}"/><CheckBox x:Name="AllowSelfSigned" Grid.Row="2" Grid.Column="2" Content="Allow self-signed certificate"/></Grid>
          <Grid Margin="0,8,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="125"/><ColumnDefinition Width="240"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Label Content="Default reason"/><ComboBox x:Name="DefaultMovementReason" Grid.Column="1" ItemTemplate="{StaticResource ReasonTemplate}" Margin="0,0,12,6"/><TextBlock Grid.Column="2" Text="Used for assignments, transfers and stock movements." Foreground="{DynamicResource MutedBrush}" TextWrapping="Wrap" VerticalAlignment="Center"/></Grid><Button x:Name="SaveAssyst" Content="Save Assyst settings" HorizontalAlignment="Right" Margin="0,8,0,0"/></StackPanel></Border>
        <Border Style="{StaticResource CardStyle}"><StackPanel><TextBlock Text="Appearance" Style="{StaticResource SectionStyle}"/><CheckBox x:Name="DarkMode" Content="Use dark mode"/></StackPanel></Border>
      </StackPanel></ScrollViewer></TabItem>
    </TabControl>
    <GridSplitter Grid.Row="2" Height="6" HorizontalAlignment="Stretch" Background="{DynamicResource BorderBrush}" ResizeDirection="Rows"/>
    <Border Grid.Row="3" Margin="14,5,14,8" Style="{StaticResource CardStyle}"><Grid>
      <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
      <DockPanel Margin="0,0,0,8" LastChildFill="False"><TextBlock Text="RESULTS" FontWeight="SemiBold" VerticalAlignment="Center" DockPanel.Dock="Left"/><StackPanel Orientation="Horizontal" DockPanel.Dock="Right"><Button x:Name="FindInResults" Content="Find (Ctrl+F)"/><Button x:Name="PreviousResult" Content="Previous"/><Button x:Name="NextResult" Content="Next result"/></StackPanel></DockPanel>
      <DockPanel x:Name="ResultSearchBar" Grid.Row="1" Visibility="Collapsed" Margin="0,0,0,8" LastChildFill="False"><TextBox x:Name="ResultSearchText" Width="260" DockPanel.Dock="Left" Margin="0,0,8,0"/><TextBlock x:Name="ResultSearchCount" Text="0 matches" VerticalAlignment="Center" Foreground="{DynamicResource MutedBrush}" DockPanel.Dock="Left"/><StackPanel Orientation="Horizontal" DockPanel.Dock="Right"><Button x:Name="FindPreviousMatch" Content="Previous match"/><Button x:Name="FindNextMatch" Content="Next match"/><Button x:Name="CloseResultSearch" Content="Close"/></StackPanel></DockPanel>
      <TextBox x:Name="Output" Grid.Row="2" Background="{DynamicResource OutputBrush}" FontFamily="Consolas" IsReadOnly="True" AcceptsReturn="True" TextWrapping="NoWrap" IsInactiveSelectionHighlightEnabled="True" SelectionBrush="{DynamicResource AccentBrush}" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto"/>
    </Grid></Border>
    <Border Grid.Row="4" Background="{DynamicResource SurfaceBrush}" BorderBrush="{DynamicResource BorderBrush}" BorderThickness="0,1,0,0"><DockPanel><Button x:Name="ToggleResults" Content="Show results" Visibility="Collapsed" DockPanel.Dock="Right" MinHeight="20" Height="22" Padding="10,1" Margin="0,2,8,2"/><TextBlock x:Name="Status" Text="Ready" Foreground="{DynamicResource MutedBrush}" Margin="14,0" VerticalAlignment="Center"/></DockPanel></Border>
  </Grid>
</Window>
'@

[xml]$xamlDocument=$xaml
$reader=New-Object System.Xml.XmlNodeReader $xamlDocument
$window=[Windows.Markup.XamlReader]::Load($reader)
$names=@('Tabs','Computer','ComputerDomain','FindComputer','DescriptionSearch','FindDescriptions','DescriptionResults','NewDescription','SaveDescription','SerialNumber','Ping','OpenCDrive','RemoteDesktop','RemoteAssistance','CopyComputer','LoggedInUser','InstalledSoftware','EnableMove','DnsDetails','ShowLaps','CopyLaps','ShowBitLocker','CopyBitLocker','AdminShell','Dsa','CompMgmt','UserIdentity','UserDomain','FindUser','UnlockUser','ResetPassword','GroupUser1','LoadGroups1','Groups1','UseUserAbove','CopyGroupList1','CopyAllGroupsTo2','CopyGroupTo2','CopyGroupTo1','GroupUser2','LoadGroups2','Groups2','CopyAllGroupsTo1','CopyGroupList2','AssystItem','FindAssystItem','UseSelectedComputer','AssystNewOwner','AssignAssystItem','MovementReason','StockSite','PutInStock','ShowDiscontinued','AssystOwner1','FindAssystOwner1','AssystDevices1','TransferToOwner2','TransferToOwner1','AssystOwner2','FindAssystOwner2','AssystDevices2','AssystContracts','ExportContracts','CredentialDomain','AdminUser','AdminPassword','SaveCredential','AssystApiBaseBox','AssystBasic','SaveAssyst','AllowSelfSigned','DarkMode','ResultsSplitterRow','ResultsRow','ToggleResults','FindInResults','PreviousResult','NextResult','ResultSearchBar','ResultSearchText','ResultSearchCount','FindPreviousMatch','FindNextMatch','CloseResultSearch','Output','Status')
foreach($name in $names){$control=$window.FindName($name);if($null -eq $control){throw "The interface control '$name' could not be loaded."};Set-Variable -Name $name -Value $control -Scope Script}
$DefaultMovementReason=$window.FindName('DefaultMovementReason');if($null -eq $DefaultMovementReason){throw "The interface control 'DefaultMovementReason' could not be loaded."}

$script:WpfStatePath=Join-Path $(if($env:LOCALAPPDATA){$env:LOCALAPPDATA}else{$env:TEMP}) 'PolyntToolbox\state.json'
$script:WpfPreviewStatePath=Join-Path $(if($env:LOCALAPPDATA){$env:LOCALAPPDATA}else{$env:TEMP}) 'PolyntToolbox\wpf-state.json'
function Read-WpfState {
    $recent=@();$recentAssyst=@();$darkMode=$false;$hasDarkPreference=$false
    if(Test-Path -LiteralPath $script:WpfStatePath){try{$s=Get-Content -LiteralPath $script:WpfStatePath -Raw|ConvertFrom-Json;$recent=@($s.Recent);if($s.PSObject.Properties['RecentAssyst']){$recentAssyst=@($s.RecentAssyst)};if($s.PSObject.Properties['DarkMode']){$darkMode=[bool]$s.DarkMode;$hasDarkPreference=$true}}catch{}}
    if(-not $hasDarkPreference -and (Test-Path -LiteralPath $script:WpfPreviewStatePath)){try{$preview=Get-Content -LiteralPath $script:WpfPreviewStatePath -Raw|ConvertFrom-Json;if($preview.PSObject.Properties['DarkMode']){$darkMode=[bool]$preview.DarkMode}}catch{}}
    @{Recent=$recent;RecentAssyst=$recentAssyst;DarkMode=$darkMode}
}
function Save-WpfState {$folder=Split-Path -Parent $script:WpfStatePath;if(-not(Test-Path -LiteralPath $folder)){[void](New-Item -ItemType Directory -Path $folder -Force)};$script:WpfState|ConvertTo-Json|Set-Content -LiteralPath $script:WpfStatePath -Encoding UTF8}
$script:WpfState=Read-WpfState;$script:DarkTheme=[bool]$script:WpfState.DarkMode

function Set-WpfBrush($Key,$Hex){$converter=New-Object Windows.Media.BrushConverter;$brush=$converter.ConvertFromString([string]$Hex);$window.Resources[$Key]=$brush}
function Copy-WpfThemeResources($Target){foreach($key in @('WindowBrush','SurfaceBrush','CardBrush','InputBrush','TextBrush','MutedBrush','BorderBrush','AccentBrush','ButtonBrush','SelectionBrush','PressedBrush','OutputBrush','ScrollThumbBrush','ScrollThumbHoverBrush','HeaderTextBrush')){$Target.Resources[$key]=$window.Resources[$key]}}
function Apply-WpfTheme {
    if($script:DarkTheme){$colors=@{WindowBrush='#0F0F0F';SurfaceBrush='#181818';CardBrush='#212121';InputBrush='#121212';TextBrush='#F1F1F1';MutedBrush='#AAAAAA';BorderBrush='#3F3F3F';AccentBrush='#3F3F3F';ButtonBrush='#272727';SelectionBrush='#3F3F3F';PressedBrush='#4A4A4A';OutputBrush='#0F0F0F';ScrollThumbBrush='#606060';ScrollThumbHoverBrush='#909090';HeaderTextBrush='#F1F1F1'}}
    else{$colors=@{WindowBrush='#F3F6FA';SurfaceBrush='#FFFFFF';CardBrush='#FFFFFF';InputBrush='#FFFFFF';TextBrush='#172033';MutedBrush='#5B687A';BorderBrush='#CBD5E1';AccentBrush='#2878D0';ButtonBrush='#EEF3F8';SelectionBrush='#DCE6F1';PressedBrush='#CCD8E5';OutputBrush='#FBFCFE';ScrollThumbBrush='#A8B2BF';ScrollThumbHoverBrush='#7C8998';HeaderTextBrush='#FFFFFF'}}
    foreach($key in $colors.Keys){Set-WpfBrush $key $colors[$key]}
    $window.Resources[[Windows.SystemColors]::WindowBrushKey]=$window.Resources['InputBrush']
    $window.Resources[[Windows.SystemColors]::WindowTextBrushKey]=$window.Resources['TextBrush']
    $window.Resources[[Windows.SystemColors]::ControlBrushKey]=$window.Resources['SurfaceBrush']
    $window.Resources[[Windows.SystemColors]::ControlTextBrushKey]=$window.Resources['TextBrush']
    $window.Resources[[Windows.SystemColors]::HighlightBrushKey]=$window.Resources['SelectionBrush']
    $window.Resources[[Windows.SystemColors]::HighlightTextBrushKey]=$window.Resources['HeaderTextBrush']
    $window.Resources[[Windows.SystemColors]::MenuBrushKey]=$window.Resources['SurfaceBrush']
    $window.Resources[[Windows.SystemColors]::MenuTextBrushKey]=$window.Resources['TextBrush']
    $menuVariable=Get-Variable -Name enableMenu -Scope Script -ErrorAction SilentlyContinue
    if($menuVariable -and $menuVariable.Value){Copy-WpfThemeResources $menuVariable.Value;$menuVariable.Value.Background=$window.Resources['SurfaceBrush'];$menuVariable.Value.Foreground=$window.Resources['TextBrush']}
}
function Set-WpfDialogTheme($Dialog){
    Copy-WpfThemeResources $Dialog;$Dialog.Background=$window.Resources['CardBrush'];$Dialog.Foreground=$window.Resources['TextBrush']
    $queue=New-Object System.Collections.Queue;$queue.Enqueue($Dialog)
    while($queue.Count){$control=$queue.Dequeue();if($control -is [Windows.Controls.TextBlock] -or $control -is [Windows.Controls.CheckBox]){$control.Foreground=$window.Resources['TextBrush'];$control.Style=$window.FindResource($control.GetType())}elseif($control -is [Windows.Controls.PasswordBox] -or $control -is [Windows.Controls.TextBox]){$control.Background=$window.Resources['InputBrush'];$control.Foreground=$window.Resources['TextBrush'];$control.BorderBrush=$window.Resources['BorderBrush'];$control.Style=$window.FindResource($control.GetType())}elseif($control -is [Windows.Controls.Button]){$control.Background=$window.Resources['ButtonBrush'];$control.Foreground=$window.Resources['TextBrush'];$control.BorderBrush=$window.Resources['BorderBrush'];$control.Style=$window.FindResource($control.GetType())};if($control -is [Windows.Controls.Panel]){foreach($child in $control.Children){$queue.Enqueue($child)}}elseif($control -is [Windows.Controls.ContentControl] -and $control.Content -is [Windows.DependencyObject]){$queue.Enqueue($control.Content)}}
}
function Set-Status($Text){$Status.Text=$Text}
$script:ResultsExpanded=$false;$script:LastResultsHeight=210
function Set-WpfResultsVisible([bool]$Visible){
    if($Visible){$maximumHeight=[Math]::Max(120,$window.ActualHeight*0.45);$height=[Math]::Min($maximumHeight,[Math]::Max(120,[double]$script:LastResultsHeight));$ResultsSplitterRow.Height=[Windows.GridLength]::new(6);$ResultsRow.Height=[Windows.GridLength]::new($height);$ToggleResults.Visibility=[Windows.Visibility]::Visible;$ToggleResults.Content='Hide results';$script:ResultsExpanded=$true}
    else{if($ResultsRow.ActualHeight -ge 120){$script:LastResultsHeight=$ResultsRow.ActualHeight};$ResultsSplitterRow.Height=[Windows.GridLength]::new(0);$ResultsRow.Height=[Windows.GridLength]::new(0);if($Output.Text){$ToggleResults.Visibility=[Windows.Visibility]::Visible;$ToggleResults.Content='Show results'}else{$ToggleResults.Visibility=[Windows.Visibility]::Collapsed};$script:ResultsExpanded=$false}
}
function Show-WpfResult($Value){if($null -eq $Value){$Output.Text='Command completed successfully.'}else{$values=@($Value);if($values.Count -and $values[0].PSObject.TypeNames -contains 'Polynt.AssystItemSummary'){$display=@('ShortCode','SerialNumber','Product','Status','OwnerEmail','CostCentreName','ContractName','Department','Supplier','AcquiredMethod','AcquiredDate','WarrantyMonths','ContractExpiry','Location','Discontinued');$Output.Text=(($values|Select-Object -Property $display|Format-List *|Out-String -Width 180).Trim())}else{$Output.Text=(($Value|Format-List *|Out-String -Width 180).Trim())}};$script:ResultIndex=0;Set-WpfResultsVisible $true;$Output.ScrollToHome();if($ResultSearchBar.Visibility -eq [Windows.Visibility]::Visible -and $ResultSearchText.Text){Find-WpfResultText 1 $true}}
function Move-WpfResult($Direction){$blocks=@([regex]::Matches($Output.Text,'(?:\r?\n){2,}'));if(-not $blocks.Count){Set-Status 'Only one result';return};$count=$blocks.Count+1;$script:ResultIndex=($script:ResultIndex+$Direction+$count)%$count;$line=0;if($script:ResultIndex){$character=$blocks[$script:ResultIndex-1].Index+$blocks[$script:ResultIndex-1].Length;$line=$Output.GetLineIndexFromCharacterIndex($character)};$Output.ScrollToLine($line);Set-Status "Result $($script:ResultIndex+1) of $count"}
function Find-WpfResultText([int]$Direction,[bool]$FromStart=$false){
    $term=$ResultSearchText.Text
    if([string]::IsNullOrEmpty($term)){$ResultSearchCount.Text='0 matches';return}
    $matches=[regex]::Matches($Output.Text,[regex]::Escape($term),[Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if(-not $matches.Count){$ResultSearchCount.Text='0 matches';$Output.Select($Output.SelectionStart,0);return}
    $origin=if($FromStart){-1}else{$Output.SelectionStart}
    $target=if($Direction -ge 0){0}else{$matches.Count-1}
    if($Direction -ge 0){for($i=0;$i -lt $matches.Count;$i++){if($matches[$i].Index -gt $origin){$target=$i;break}}}
    else{for($i=$matches.Count-1;$i -ge 0;$i--){if($matches[$i].Index -lt $origin){$target=$i;break}}}
    $match=$matches[$target]
    $Output.Select($match.Index,$match.Length)
    $Output.ScrollToLine($Output.GetLineIndexFromCharacterIndex($match.Index))
    $ResultSearchCount.Text="$($target+1) of $($matches.Count)"
}
function Open-WpfResultSearch {Set-WpfResultsVisible $true;$ResultSearchBar.Visibility=[Windows.Visibility]::Visible;$ResultSearchText.Focus()|Out-Null;$ResultSearchText.SelectAll();if($ResultSearchText.Text){Find-WpfResultText 1 $true}}
function Close-WpfResultSearch {$ResultSearchBar.Visibility=[Windows.Visibility]::Collapsed;$Output.Select($Output.SelectionStart,0);$Output.Focus()|Out-Null}
function Invoke-Wpf($Activity,[scriptblock]$Action){
    try{$window.Cursor='Wait';Set-Status $Activity;Show-WpfResult (& $Action);Set-Status "Completed: $Activity"}
    catch{
        $message=$_.Exception.Message
        if($message -like 'MISSING_REQUIREMENT:*'){
            $parts=$message.Split('|',2);$requirement=$parts[0].Substring('MISSING_REQUIREMENT:'.Length)
            if([Windows.MessageBox]::Show($window,"$($parts[-1])`r`n`r`nInstall $requirement now?",'Missing requirement','YesNo','Question') -eq 'Yes'){
                try{Install-PolyntRequirement -Requirement $requirement;Show-WpfResult (& $Action);Set-Status "Completed: $Activity";return}catch{$message=$_.Exception.Message}
            }
        }
        Set-Status "Failed: $Activity";$Output.Text=$message;Set-WpfResultsVisible $true;if($ResultSearchBar.Visibility -eq [Windows.Visibility]::Visible -and $ResultSearchText.Text){Find-WpfResultText 1 $true};[void][Windows.MessageBox]::Show($window,$message,'Polynt IT Toolbox','OK','Error')
    }finally{$window.Cursor=$null}
}
function Require-WpfText($Control,$Name){if([string]::IsNullOrWhiteSpace($Control.Text)){throw "$Name is required."};$Control.Text.Trim()}
function Fill-Domains($Combo){$Combo.ItemsSource=@('Polynt (.net)','Polynt (.us)','Resins','Reichhold');$Combo.SelectedIndex=0}
function Fill-CredentialDomains($Combo){$Combo.ItemsSource=@('polynt.net','polynt.us','rsn.chem.corp.local','apac.reichhold.com');$Combo.SelectedIndex=0}
function Get-WpfDomain($Combo){switch($Combo.SelectedIndex){1{'polynt.us'}2{'resins'}3{'reichhold'}default{'polynt'}}}
function Refresh-WpfCredentialUser {$AdminUser.Text=Get-PolyntCredentialUserName -Domain (Get-WpfDomain $CredentialDomain);$AdminPassword.Clear()}
function Confirm-Wpf($Message,$Title){[Windows.MessageBox]::Show($window,$Message,$Title,'YesNo','Warning') -eq 'Yes'}
function Add-WpfEnterAction($Control,$Button){$Control.Tag=$Button;$Control.Add_KeyDown({param($sender,$eventArgs);if($eventArgs.Key -eq [Windows.Input.Key]::Enter){$eventArgs.Handled=$true;$sender.Tag.RaiseEvent([Windows.RoutedEventArgs]::new([Windows.Controls.Button]::ClickEvent))}})}
function Refresh-WpfRecent {$current=$Computer.Text;$Computer.ItemsSource=$null;$Computer.ItemsSource=@($script:WpfState.Recent);$Computer.Text=$current}
function Get-WpfComputer {$name=Require-WpfText $Computer 'Computer name';$script:WpfState.Recent=@(@($name)+@($script:WpfState.Recent|Where-Object{$_ -ne $name})|Select-Object -First 15);Save-WpfState;Refresh-WpfRecent;$name}
function Refresh-WpfAssystRecent {$current=$AssystItem.Text;$AssystItem.ItemsSource=$null;$AssystItem.ItemsSource=@($script:WpfState.RecentAssyst);$AssystItem.Text=$current}
function Add-WpfAssystRecent($Name){$nameText=[string]$Name;if([string]::IsNullOrWhiteSpace($nameText)){return};$nameText=$nameText.Trim();$script:WpfState.RecentAssyst=@(@($nameText)+@($script:WpfState.RecentAssyst|Where-Object{$_ -ine $nameText})|Select-Object -First 15);Save-WpfState;Refresh-WpfAssystRecent}
function Get-WpfAssystItem {$name=Require-WpfText $AssystItem 'Item short code';Add-WpfAssystRecent $name;$name}
function New-ReasonItems {@([pscustomobject]@{Name='Acquisition';Code='ACQUISITION'},[pscustomobject]@{Name='Customer Request';Code='CUSTOMER REQ'},[pscustomobject]@{Name='Illegal Movement';Code='ILLEGAL MOVE'},[pscustomobject]@{Name='Initial Load Into CMDB';Code='INITIAL LOAD'},[pscustomobject]@{Name='Project Movement';Code='PROJECT MOVE'},[pscustomobject]@{Name='Replacement';Code='REPLACEMENT'},[pscustomobject]@{Name='Retirement';Code='RETIREMENT'})}
function Set-ReasonSelection($Combo,[string]$Code){$match=@($Combo.ItemsSource|Where-Object{$_.Code -eq $Code}|Select-Object -First 1);if($match.Count){$Combo.SelectedItem=$match[0]}else{$Combo.SelectedIndex=1}}
function New-DeviceEntry($Device){[pscustomobject]@{DisplayText="$($Device.ShortCode) - $($Device.Product) - $($Device.Status)";Discontinued=[bool]$Device.Discontinued;Item=$Device}}
$script:OwnerData=@{One=[pscustomobject]@{Email='';Devices=@()};Two=[pscustomobject]@{Email='';Devices=@()}}
function Refresh-OwnerList($Side){$data=$script:OwnerData[$Side];$view=@($data.Devices|Where-Object{$ShowDiscontinued.IsChecked -or -not $_.Discontinued}|Sort-Object @{Expression={$_.Discontinued}},ShortCode|ForEach-Object{New-DeviceEntry $_});if($Side -eq 'One'){$AssystDevices1.ItemsSource=$view}else{$AssystDevices2.ItemsSource=$view}}
function Search-Owner($Side,$EmailBox){$email=Require-WpfText $EmailBox 'Owner email address';$devices=@(Get-AssystItemsByOwnerEmail -EmailAddress $email);$script:OwnerData[$Side]=[pscustomobject]@{Email=$email;Devices=$devices};Refresh-OwnerList $Side;$devices}
function Sync-OwnerLists($Device,$Email){foreach($side in @('One','Two')){$data=$script:OwnerData[$side];$data.Devices=@($data.Devices|Where-Object{$_.ShortCode -ne $Device.ShortCode});if($data.Email -ieq $Email){$data.Devices=@($data.Devices)+@($Device)};Refresh-OwnerList $side}}
function Transfer-OwnerDevice($From,$To,$DestinationBox,$List){if(-not $List.SelectedItem){[void][Windows.MessageBox]::Show($window,'Select a device first.','Assets','OK','Information');return};$email=$DestinationBox.Text.Trim();if(-not $email -or $script:OwnerData[$To].Email -ine $email){[void][Windows.MessageBox]::Show($window,'Enter and search the destination owner first.','Assets','OK','Information');return};$entry=$List.SelectedItem;$reason=$MovementReason.SelectedItem;if(Confirm-Wpf "Assign $($entry.Item.ShortCode) to $email using '$($reason.Name)'?" 'Confirm Assyst transfer'){Invoke-Wpf 'Transferring Assyst item' {$updated=Set-AssystItemOwner -ItemId ([long]$entry.Item.ItemId) -NewOwnerEmail $email -StatusName 'Deployed' -MovementReason $reason.Code -Confirm:$false;Sync-OwnerLists $updated $email;$updated}}}
function Load-GroupList($Number){$box=if($Number -eq 1){$GroupUser1}else{$GroupUser2};$list=if($Number -eq 1){$Groups1}else{$Groups2};$user=Require-WpfText $box "User $Number";$items=@(Get-PolyntADUserGroups -Identity $user -Domain (Get-WpfDomain $UserDomain));$list.ItemsSource=$items;$list.Tag=$user;$items}
function Copy-OneGroup($From,$To){$source=if($From -eq 1){$Groups1}else{$Groups2};$target=if($To -eq 1){$Groups1}else{$Groups2};$targetBox=if($To -eq 1){$GroupUser1}else{$GroupUser2};if(-not $source.SelectedItem){[void][Windows.MessageBox]::Show($window,"Select a group in User $From first.",'Users & Groups','OK','Information');return};$user=Require-WpfText $targetBox "User $To";if([string]$target.Tag -ine $user){[void][Windows.MessageBox]::Show($window,"Load User $To groups first.",'Users & Groups','OK','Information');return};$group=$source.SelectedItem;if(Confirm-Wpf "Add '$($group.Name)' to $user?" 'Confirm group membership'){Invoke-Wpf 'Adding group membership' {$result=Add-PolyntADUserGroup -GroupIdentity $group.DistinguishedName -TargetUser $user -Domain (Get-WpfDomain $UserDomain) -Confirm:$false;Load-GroupList $To|Out-Null;$result}}}
function Copy-AllGroups($From,$To){$fromBox=if($From -eq 1){$GroupUser1}else{$GroupUser2};$toBox=if($To -eq 1){$GroupUser1}else{$GroupUser2};$source=Require-WpfText $fromBox "User $From";$target=Require-WpfText $toBox "User $To";if(Confirm-Wpf "Copy every missing direct group from $source to $target?" 'Confirm group transfer'){Invoke-Wpf 'Copying missing groups' {$result=Copy-PolyntADUserGroups -SourceUser $source -TargetUser $target -Domain (Get-WpfDomain $UserDomain) -Confirm:$false;Load-GroupList $To|Out-Null;$result}}}

Fill-Domains $ComputerDomain;Fill-Domains $UserDomain;Fill-CredentialDomains $CredentialDomain;Refresh-WpfRecent;Refresh-WpfAssystRecent
$reasonItems=New-ReasonItems;$MovementReason.ItemsSource=$reasonItems;$DefaultMovementReason.ItemsSource=$reasonItems;Set-ReasonSelection $MovementReason $script:AssystDefaultMovementReason;Set-ReasonSelection $DefaultMovementReason $script:AssystDefaultMovementReason
$StockSite.ItemsSource=@('Drocourt','Bordeaux');$StockSite.SelectedIndex=0
Refresh-WpfCredentialUser;$CredentialDomain.Add_SelectionChanged({Refresh-WpfCredentialUser});$AssystApiBaseBox.Text=$script:AssystApiBase;$AllowSelfSigned.IsChecked=$script:AssystAllowUntrustedCertificate;$DarkMode.IsChecked=$script:DarkTheme;Apply-WpfTheme

$FindComputer.Add_Click({Invoke-Wpf 'Looking up computer' {Get-PC -Name (Get-WpfComputer) -Domain (Get-WpfDomain $ComputerDomain)}})
$FindDescriptions.Add_Click({Invoke-Wpf 'Searching AD descriptions' {$items=@(Get-PC-Desc -Description (Require-WpfText $DescriptionSearch 'Description') -Domain (Get-WpfDomain $ComputerDomain)|Sort-Object Name|ForEach-Object{[pscustomobject]@{Name=$_.Name;Description=$_.Description;DisplayText="$($_.Name) - $($_.Description)"}});$DescriptionResults.ItemsSource=$items;if($items.Count){$DescriptionResults.SelectedIndex=0};$items}})
$DescriptionResults.Add_SelectionChanged({if($DescriptionResults.SelectedItem){$Computer.Text=$DescriptionResults.SelectedItem.Name;$NewDescription.Text=$DescriptionResults.SelectedItem.Description;Set-Status "Selected $($Computer.Text)"}})
$SaveDescription.Add_Click({if(Confirm-Wpf "Update $($Computer.Text)'s AD description?" 'Confirm change'){Invoke-Wpf 'Updating AD description' {Set-PC-Desc -Computer (Get-WpfComputer) -Description $NewDescription.Text -Domain (Get-WpfDomain $ComputerDomain) -Confirm:$false}}})
$SerialNumber.Add_Click({Invoke-Wpf 'Reading remote inventory' {Get-SN -Name (Get-WpfComputer) -Domain (Get-WpfDomain $ComputerDomain)}});$Ping.Add_Click({Invoke-Wpf 'Testing connectivity' {Test-Connection -ComputerName (Get-WpfComputer) -Count 2 -ErrorAction Stop|Select-Object Address,IPv4Address,ResponseTime,StatusCode}})
$OpenCDrive.Add_Click({Invoke-Wpf 'Opening remote C drive' {Start-PolyntRemoteCDrive -Computer (Get-WpfComputer) -Domain (Get-WpfDomain $ComputerDomain)}});$RemoteDesktop.Add_Click({Invoke-Wpf 'Starting Remote Desktop' {Start-PolyntRemoteDesktop -Computer (Get-WpfComputer) -Domain (Get-WpfDomain $ComputerDomain)}});$RemoteAssistance.Add_Click({Invoke-Wpf 'Starting Remote Assistance' {Start-Msra -Computer (Get-WpfComputer) -Domain (Get-WpfDomain $ComputerDomain)}})
$CopyComputer.Add_Click({if($Computer.Text){[Windows.Clipboard]::SetText($Computer.Text.Trim());Set-Status 'Computer name copied'}});$LoggedInUser.Add_Click({Invoke-Wpf 'Querying logged-in user' {Get-RemoteSession -Computer (Get-WpfComputer) -Domain (Get-WpfDomain $ComputerDomain)}});$InstalledSoftware.Add_Click({Invoke-Wpf 'Reading installed software' {Get-RemoteSoftware -Computer (Get-WpfComputer) -Domain (Get-WpfDomain $ComputerDomain)}});$DnsDetails.Add_Click({Invoke-Wpf 'Looking up DNS records' {Resolve-DnsName -Name (Get-WpfComputer) -ErrorAction Stop|Select-Object Name,Type,IPAddress,NameHost}})
$enableMenu=New-Object Windows.Controls.ContextMenu;$enableMenu.Style=$window.FindResource([Windows.Controls.ContextMenu]);$enableMenu.PlacementTarget=$EnableMove;$enableMenu.Placement=[Windows.Controls.Primitives.PlacementMode]::Bottom;foreach($site in @('Drocourt','Bordeaux')){$item=New-Object Windows.Controls.MenuItem;$item.Style=$window.FindResource([Windows.Controls.MenuItem]);$item.Header="Enable and move to $site";$item.Tag=$site;$item.Add_Click({param($sender,$eventArgs);try{$selectedSite=[string]$sender.Tag;$selectedComputer=Get-WpfComputer;$selectedDomain=Get-WpfDomain $ComputerDomain;if(Confirm-Wpf "Enable $selectedComputer and move it to $selectedSite?" 'Confirm computer change'){$action={Enable-PC -Computer $selectedComputer -Site $selectedSite -Domain $selectedDomain -Confirm:$false}.GetNewClosure();Invoke-Wpf 'Enabling and moving computer' $action}}catch{$message=$_.Exception.Message;Set-Status 'Failed: Enable / move';[void][Windows.MessageBox]::Show($window,$message,'Enable / move','OK','Error')}});[void]$enableMenu.Items.Add($item)};$EnableMove.ContextMenu=$enableMenu;$EnableMove.Add_Click({$EnableMove.ContextMenu.IsOpen=$true})
$script:LastLaps=$null;$script:LastBitLocker=@();$ShowLaps.Add_Click({Invoke-Wpf 'Retrieving LAPS password' {$script:LastLaps=Get-PolyntLapsPwd -Computer (Get-WpfComputer) -Domain (Get-WpfDomain $ComputerDomain);$script:LastLaps}});$CopyLaps.Add_Click({if($script:LastLaps -and $script:LastLaps.Password){[Windows.Clipboard]::SetText([string]$script:LastLaps.Password);Set-Status 'LAPS password copied'}else{[void][Windows.MessageBox]::Show($window,'Retrieve a LAPS password first.','Computer','OK','Information')}});$ShowBitLocker.Add_Click({Invoke-Wpf 'Retrieving BitLocker keys' {$script:LastBitLocker=@(Get-BitLockerRecoveryKey -Computer (Get-WpfComputer) -Domain (Get-WpfDomain $ComputerDomain));$script:LastBitLocker}});$CopyBitLocker.Add_Click({if($script:LastBitLocker.Count -and $script:LastBitLocker[0].RecoveryPassword){[Windows.Clipboard]::SetText([string]$script:LastBitLocker[0].RecoveryPassword);Set-Status 'Newest BitLocker key copied'}else{[void][Windows.MessageBox]::Show($window,'Retrieve a BitLocker recovery key first.','Computer','OK','Information')}})

$AdminShell.Add_Click({Invoke-Wpf 'Opening admin PowerShell' {Get-PolyntAdmin -Domain (Get-WpfDomain $ComputerDomain)}});$Dsa.Add_Click({Invoke-Wpf 'Opening AD Users and Computers' {Start-Dsa -Domain (Get-WpfDomain $ComputerDomain)}});$CompMgmt.Add_Click({Invoke-Wpf 'Opening Computer Management' {Start-Compmgmt -Domain (Get-WpfDomain $ComputerDomain)}})
$FindUser.Add_Click({Invoke-Wpf 'Searching Active Directory' {Find-PolyntADUser -Identity (Require-WpfText $UserIdentity 'User identity') -Domain (Get-WpfDomain $UserDomain)}});$UnlockUser.Add_Click({if(Confirm-Wpf "Unlock $($UserIdentity.Text)?" 'Confirm account change'){Invoke-Wpf 'Unlocking account' {Unlock-PolyntADUser -Identity (Require-WpfText $UserIdentity 'User identity') -Domain (Get-WpfDomain $UserDomain) -Confirm:$false}}})
$ResetPassword.Add_Click({$identity=$UserIdentity.Text.Trim();if(-not $identity){[void][Windows.MessageBox]::Show($window,'Enter a user first.','Reset password','OK','Information');return};$dialog=New-Object Windows.Window -Property @{Title='Reset AD password';Width=430;Height=270;WindowStartupLocation='CenterOwner';Owner=$window;ResizeMode='NoResize'};$panel=New-Object Windows.Controls.StackPanel -Property @{Margin=20};$panel.Children.Add((New-Object Windows.Controls.TextBlock -Property @{Text="New password for $identity";FontWeight='SemiBold';Margin='0,0,0,12'}))|Out-Null;$p1=New-Object Windows.Controls.PasswordBox -Property @{Margin='0,0,0,10';Padding=7};$p2=New-Object Windows.Controls.PasswordBox -Property @{Margin='0,0,0,10';Padding=7};$change=New-Object Windows.Controls.CheckBox -Property @{Content='Require password change at next login';IsChecked=$true;Margin='0,0,0,14'};$buttons=New-Object Windows.Controls.WrapPanel -Property @{HorizontalAlignment='Right'};$ok=New-Object Windows.Controls.Button -Property @{Content='Reset password';Padding='12,7';Margin='0,0,8,0'};$cancel=New-Object Windows.Controls.Button -Property @{Content='Cancel';Padding='12,7';IsCancel=$true};foreach($c in @($p1,$p2,$change,$buttons)){[void]$panel.Children.Add($c)};[void]$buttons.Children.Add($ok);[void]$buttons.Children.Add($cancel);$dialog.Content=$panel;Set-WpfDialogTheme $dialog;$ok.Add_Click({if(-not $p1.Password -or $p1.Password -cne $p2.Password){[void][Windows.MessageBox]::Show($dialog,'Enter matching passwords.','Reset password','OK','Information');return};$dialog.DialogResult=$true});if($dialog.ShowDialog()){$secure=ConvertTo-SecureString $p1.Password -AsPlainText -Force;Invoke-Wpf 'Resetting AD password' {Reset-PolyntADUserPassword -Identity $identity -NewPassword $secure -RequireChangeAtLogin ([bool]$change.IsChecked) -Domain (Get-WpfDomain $UserDomain) -Confirm:$false}}})
$UseUserAbove.Add_Click({if($UserIdentity.Text){$GroupUser1.Text=$UserIdentity.Text.Trim();$GroupUser1.Focus()|Out-Null}});$LoadGroups1.Add_Click({Invoke-Wpf 'Loading User 1 groups' {Load-GroupList 1}});$LoadGroups2.Add_Click({Invoke-Wpf 'Loading User 2 groups' {Load-GroupList 2}});$CopyGroupTo2.Add_Click({Copy-OneGroup 1 2});$CopyGroupTo1.Add_Click({Copy-OneGroup 2 1});$CopyAllGroupsTo2.Add_Click({Copy-AllGroups 1 2});$CopyAllGroupsTo1.Add_Click({Copy-AllGroups 2 1});$CopyGroupList1.Add_Click({if($Groups1.Items.Count){[Windows.Clipboard]::SetText((@($Groups1.Items|ForEach-Object{$_.Name})-join [Environment]::NewLine));Set-Status 'User 1 group list copied'}});$CopyGroupList2.Add_Click({if($Groups2.Items.Count){[Windows.Clipboard]::SetText((@($Groups2.Items|ForEach-Object{$_.Name})-join [Environment]::NewLine));Set-Status 'User 2 group list copied'}})

$FindAssystItem.Add_Click({Invoke-Wpf 'Finding Assyst item' {Get-AssystItemDirectMatch -ShortCode (Get-WpfAssystItem)}});$UseSelectedComputer.Add_Click({if($Computer.Text){$AssystItem.Text=$Computer.Text.Trim();Add-WpfAssystRecent $AssystItem.Text;$AssystItem.Focus()|Out-Null}});$FindAssystOwner1.Add_Click({Invoke-Wpf 'Finding Owner 1 devices' {Search-Owner 'One' $AssystOwner1}});$FindAssystOwner2.Add_Click({Invoke-Wpf 'Finding Owner 2 devices' {Search-Owner 'Two' $AssystOwner2}});$ShowDiscontinued.Add_Checked({Refresh-OwnerList 'One';Refresh-OwnerList 'Two'});$ShowDiscontinued.Add_Unchecked({Refresh-OwnerList 'One';Refresh-OwnerList 'Two'})
$AssystDevices1.Add_SelectionChanged({if($AssystDevices1.SelectedItem){$AssystItem.Text=$AssystDevices1.SelectedItem.Item.ShortCode;Add-WpfAssystRecent $AssystItem.Text;Show-WpfResult $AssystDevices1.SelectedItem.Item}});$AssystDevices2.Add_SelectionChanged({if($AssystDevices2.SelectedItem){$AssystItem.Text=$AssystDevices2.SelectedItem.Item.ShortCode;Add-WpfAssystRecent $AssystItem.Text;Show-WpfResult $AssystDevices2.SelectedItem.Item}});$TransferToOwner2.Add_Click({Transfer-OwnerDevice 'One' 'Two' $AssystOwner2 $AssystDevices1});$TransferToOwner1.Add_Click({Transfer-OwnerDevice 'Two' 'One' $AssystOwner1 $AssystDevices2})
$AssignAssystItem.Add_Click({$code=$AssystItem.Text.Trim();$email=$AssystNewOwner.Text.Trim();$reason=$MovementReason.SelectedItem;if(-not $code -or -not $email){[void][Windows.MessageBox]::Show($window,'Enter an item and the user email address.','Assets','OK','Information');return};Add-WpfAssystRecent $code;if(Confirm-Wpf "Assign $code to $email using '$($reason.Name)'?" 'Confirm Assyst assignment'){Invoke-Wpf 'Assigning Assyst item' {$items=@(Get-AssystItemDirectMatch -ShortCode $code);if($items.Count -ne 1){throw "Expected one exact item for '$code'."};$updated=Set-AssystItemOwner -ItemId ([long]$items[0].ItemId) -NewOwnerEmail $email -StatusName 'Deployed' -MovementReason $reason.Code -Confirm:$false;Sync-OwnerLists $updated $email;$updated}}});$PutInStock.Add_Click({$code=$AssystItem.Text.Trim();$site=[string]$StockSite.SelectedItem;$reason=$MovementReason.SelectedItem;if(-not $code){return};Add-WpfAssystRecent $code;if(Confirm-Wpf "Put $code in $site stock using '$($reason.Name)'?" 'Confirm stock movement'){Invoke-Wpf 'Putting item in stock' {$updated=Set-AssystItemInStock -ShortCode $code -Site $site -MovementReason $reason.Code -Confirm:$false;$email=if($site -eq 'Drocourt'){'GENERIC-FR-DRT-IT@polynt.net'}else{'GENERIC-FR-BOR-IT@polynt.net'};Sync-OwnerLists $updated $email;$updated}}})
$ExportContracts.Add_Click({$text=$AssystContracts.Text.Trim();if(-not $text){return};$numbers=@($text-split '[,;\r\n]+'|ForEach-Object{$_.Trim()}|Where-Object{$_});$contractLabel=(($numbers -join '-') -replace '[<>:"/\\|?*]','_' -replace '\s+','_').Trim('._-');if($contractLabel.Length -gt 80){$contractLabel=$contractLabel.Substring(0,80).Trim('._-')};if(-not $contractLabel){$contractLabel='contract'};$dialog=New-Object Microsoft.Win32.SaveFileDialog;$dialog.Filter='CSV files (*.csv)|*.csv';$dialog.FileName="assyst-$contractLabel-items-$([DateTime]::Now.ToString('yyyyMMdd')).csv";if($dialog.ShowDialog($window)){Invoke-Wpf 'Exporting contract items' {Export-AssystContractItems -ContractNumber $numbers -Path $dialog.FileName}}})

$SaveCredential.Add_Click({Invoke-Wpf 'Saving administrator credential' {$user=Require-WpfText $AdminUser 'Username';if(-not $AdminPassword.Password){throw 'Administrator password is required.'};$result=Set-PolyntCredential -UserName $user -Password $AdminPassword.SecurePassword -Domain (Get-WpfDomain $CredentialDomain);$AdminPassword.Clear();$result}});$SaveAssyst.Add_Click({Invoke-Wpf 'Saving Assyst settings' {$reason=$DefaultMovementReason.SelectedItem;if(-not $reason){throw 'Choose a default movement reason.'};$p=@{ApiBase=(Require-WpfText $AssystApiBaseBox 'Assyst API base URL');AllowUntrustedCertificate=[bool]$AllowSelfSigned.IsChecked;DefaultMovementReason=$reason.Code};if($AssystBasic.Password){$p.BasicValue=ConvertTo-SecureString $AssystBasic.Password -AsPlainText -Force};Set-AssystSettings @p;$AssystBasic.Clear();Set-ReasonSelection $MovementReason $script:AssystDefaultMovementReason;'Assyst settings saved.'}})
